class Solution { fun boxDelivering(boxes:Array<IntArray>,portsCount:Int,maxBoxes:Int,maxWeight:Int):Int{val n=boxes.size;val weight=LongArray(n+1);val change=IntArray(n+2);for(i in 1..n){weight[i]=weight[i-1]+boxes[i-1][1];change[i]=change[i-1]+if(i>1&&boxes[i-1][0]!=boxes[i-2][0])1 else 0};change[n+1]=change[n];val dp=IntArray(n+1);val deque=java.util.ArrayDeque<Int>();deque.addLast(0);for(i in 1..n){while(i-deque.first>maxBoxes||weight[i]-weight[deque.first]>maxWeight)deque.removeFirst();val previous=deque.first;dp[i]=dp[previous]+change[i]-change[previous+1]+2;if(i<n){val value=dp[i]-change[i+1];while(deque.isNotEmpty()&&dp[deque.last]-change[deque.last+1]>=value)deque.removeLast();deque.addLast(i)}};return dp[n]} }
